$path = 'J:\REACT NATIVE APPS\DeenIslam\admin-panel\app\islamic-lifestyle\page.tsx'
$s = [IO.File]::ReadAllText($path)
$startMarker = '<div className="markdownToolbar"'
$endMarker = '</div><textarea ref={editorRef}'
$start = $s.IndexOf($startMarker)
$end = $s.IndexOf($endMarker, $start)
if ($start -lt 0 -or $end -lt 0) { throw 'Markdown toolbar block not found.' }
$toolbar = '<div className="markdownToolbar" role="toolbar" aria-label="Markdown formatting"><button type="button" title="Make selected text bold" onClick={()=>format("**","**","Bold text")}><b>B</b><span>Bold</span></button><button type="button" title="Make selected text italic" onClick={()=>format("*","*","Italic text")}><em>I</em><span>Italic</span></button><button type="button" title="Add a section heading" onClick={()=>format("## ","","Section heading")}><b>H</b><span>Heading</span></button><button type="button" title="Format selected lines as a quote" onClick={()=>lineFormat("> ","Quoted text")}><b>&gt;</b><span>Quote</span></button><button type="button" title="Create a bullet list" onClick={()=>lineFormat("- ")}><b>-</b><span>Bullets</span></button><button type="button" title="Create a numbered list" onClick={()=>lineFormat("1. ")}><b>1.</b><span>Numbers</span></button><button type="button" title="Insert a web link" onClick={()=>format("[","](https://example.com)","Link text")}><b>@</b><span>Link</span></button><button type="button" title="Insert an image URL" onClick={()=>format("![","](https://example.com/image.jpg)","Image description")}><b>IMG</b><span>Image</span></button><button type="button" className={preview?"selected":""} title="Show formatted preview" onClick={()=>setPreview(value=>!value)}><b>O</b><span>Preview</span></button><button type="button" className={markdownHelp?"selected":""} title="Show Markdown instructions" onClick={()=>setMarkdownHelp(value=>!value)}><b>?</b><span>Help</span></button></div><textarea ref={editorRef}'
$s = $s.Remove($start, ($end + $endMarker.Length) - $start).Insert($start, $toolbar)
$pattern = '\.markdownToolbar\{.*?\.markdownToolbar button\.selected\{.*?\}'
$css = '.markdownToolbar{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:9px;border:1px solid #292929;border-bottom:0;border-radius:9px 9px 0 0;background:#303030}.markdownToolbar button{height:34px;padding:5px 10px;border:1px solid #555;border-radius:6px;background:#3b3b3b;color:#fff;display:flex;align-items:center;gap:6px;font:600 11px Arial,sans-serif}.markdownToolbar button b,.markdownToolbar button em{min-width:13px;font:700 14px Georgia,serif;color:#d9f0e0}.markdownToolbar button:hover{background:#505050;border-color:#777}.markdownToolbar button.selected{background:#087a4d;border-color:#20a46e;color:#fff}'
$updated = [regex]::Replace($s, $pattern, $css, [Text.RegularExpressions.RegexOptions]::Singleline)
if ($updated -eq $s) { throw 'Toolbar CSS block not found.' }
[IO.File]::WriteAllText($path, $updated, (New-Object Text.UTF8Encoding($false)))
